const MotionTrial*AnalysisPanel::trial()const{if(!analysis_||!analysis_->directory||selected_<1||selected_>analysis_->directory->trials.size())return nullptr;return analysis_->directory->trials[size_t(selected_-1)].get();}
const FirstContactEvent*AnalysisPanel::event()const{if(!analysis_||selected_<1||selected_>analysis_->events.size())return nullptr;return analysis_->events[size_t(selected_-1)].get();}
const std::vector<std::shared_ptr<const DisplayTrajectory>>&AnalysisPanel::trajectories()const{static const std::vector<std::shared_ptr<const DisplayTrajectory>>empty;if(loaded_)return loaded_->trajectories;return analysis_?analysis_->trajectories:empty;}
void AnalysisPanel::log(const char*action){if(log_)*log_<<"timeline action="<<action<<" trial="<<selected_<<" cursor="<<cursor_<<" following="<<follow_<<" playing="<<playing_<<" physics_updates="<<physicsUpdateCount()<<'\n';}
void AnalysisPanel::seek(double time,const char*action,bool pause){auto t=trial();if(!t||!t->frames)return;cursor_=std::clamp(time,t->firstTime,t->lastTime);follow_=false;if(pause)playing_=false;eventPose_=false;needSeek_=true;log(action);}
void AnalysisPanel::select(std::uint64_t id,const char*action){if(!analysis_||id<1||id>analysis_->directory->trials.size())return;selected_=id;follow_=playing_=capturing_=eventPose_=false;sample_.reset();reader_.invalidate();cursor_=trial()->firstTime;std::snprintf(trialText_.data(),trialText_.size(),"%llu",static_cast<unsigned long long>(id));needSeek_=true;log(action);}
void AnalysisPanel::rebuildList(){listedIds_.clear();listLabels_.clear();if(!analysis_)return;for(const auto&t:analysis_->directory->trials){const auto&e=analysis_->events[size_t(t->id-1)];if(tab_==1&&selectedCell_&&(!e||e->status!=FirstContactStatus::hit||!normalCompletion(e->trialStatus)||e->cell!=*selectedCell_))continue;listedIds_.push_back(t->id);listLabels_.push_back(std::to_string(t->id)+"  "+t->status+(t->frames?"":" / no history"));}listActive_=-1;for(size_t i=0;i<listedIds_.size();++i)if(listedIds_[i]==selected_)listActive_=int(i);listScroll_=std::clamp(listScroll_,0,std::max(0,int(listedIds_.size())-1));}
AnalysisPanel::Plot AnalysisPanel::plot()const{
    if(!config_||!analysis_)return {Grid3D({{0,0,0},{1,1,1},{1,1,1}})};
    if(tab_==0)return {analysis_->route->grid(),&analysis_->route->hits(),config_->source.count,analysis_->route->completed(),0,0,analysis_->routeRecorded};
    if(tab_==1)return {analysis_->contact->grid(),&analysis_->contact->hits(),config_->source.count,analysis_->contact->known(),analysis_->contact->hitTrials(),analysis_->contact->missTrials(),analysis_->contactRecorded&&analysis_->contact->enabled()};
    const auto&g=config_->grid;int axis=tab_==2?1:2;return {Grid3D({{g.lower.x,g.lower[axis],0},{g.upper.x,g.upper[axis],1},{g.cell.x,g.cell[axis],1}}),tab_==2?&analysis_->toeXY:&analysis_->toeXZ,config_->source.count,analysis_->normalTrials,0,0,!analysis_->ioError};
}
void AnalysisPanel::sync(const SessionView&view,double elapsed,std::ostream&output){
    log_=&output;config_=view.config;followAvailable_=view.phase==SessionPhase::preview&&!view.workerFinished&&view.trialId<=2;historyContext_=bool(view.analysis);
    if(!view.analysis){if(analysis_){renderer_.clear();trajectoryReader_.cancel();reader_.invalidate();}analysis_.reset();location_.reset();loaded_.reset();sample_.reset();follow_=true;playing_=capturing_=editing_=false;return;}
    bool newRun=location_!=view.analysis->directory->location,changed=analysis_!=view.analysis;analysis_=view.analysis;
    if(newRun){location_=analysis_->directory->location;renderer_.clear();trajectoryReader_.cancel();reader_.invalidate();loaded_.reset();sample_.reset();readError_.clear();selected_=1;cursor_=0;follow_=!view.archive;playing_=capturing_=editing_=eventPose_=false;needSeek_=bool(view.archive);selectedCell_.reset();traceVersion_=surfaceVersion_=0;lastTab_=lastMetric_=-1;std::snprintf(trialText_.data(),trialText_.size(),"1");if(view.archive)trajectoryReader_.request(analysis_->directory,config_->source.history.displayVertices);}
    if(view.archive){auto loaded=trajectoryReader_.view();if(loaded&&loaded!=loaded_){loaded_=loaded;if(!loaded_->error.empty()){readError_=loaded_->error;playing_=false;}if(!loaded_->error.empty())output<<"archive_trajectory_error="<<loaded_->error<<'\n';}}
    if(follow_&&followAvailable_){selected_=view.trialId;cursor_=view.snapshot.time;std::snprintf(trialText_.data(),trialText_.size(),"%llu",static_cast<unsigned long long>(selected_));}
    else if(follow_&&(view.phase==SessionPhase::background||view.phase==SessionPhase::finished||(view.phase==SessionPhase::generating&&view.trialId>2))){if(selected_<=2)cursor_=view.snapshot.time;follow_=false;needSeek_=true;log("background_follow_disabled");}
    auto sample=reader_.latest();if(sample&&sample->request==request_&&sample->trialId==selected_){sample_=sample;if(!sample->available&&!sample->error.empty()){readError_=sample->error;playing_=false;}if(sample->request!=lastLoggedRequest_&&(!playing_||std::abs(sample->snapshot.time-lastLoggedTime_)>=.25)){output<<"history_pose trial="<<selected_<<" time="<<sample->snapshot.time<<" interpolated="<<sample->interpolated<<" available="<<sample->available<<" error="<<sample->error<<" physics_updates="<<physicsUpdateCount()<<'\n';lastLoggedRequest_=sample->request;lastLoggedTime_=sample->snapshot.time;}}
    if(playing_&&!follow_){auto t=trial();if(t&&t->frames){double before=cursor_;cursor_=std::min(t->lastTime,cursor_+std::max(0.,elapsed)*speed_);if(cursor_>=t->lastTime)playing_=false;auto e=event();if(e&&e->status==FirstContactStatus::hit&&before<e->timeLower&&cursor_>e->timeUpper){cursor_=(e->timeLower+e->timeUpper)/2;eventPose_=true;}else if(eventPose_&&e&&cursor_>e->timeUpper)eventPose_=false;needSeek_=true;}}
    if(changed&&!follow_&&!sample_&&trial()&&trial()->frames)needSeek_=true;
    if(needSeek_&&!follow_){auto t=trial();if(t&&(t->frames||eventPose_)){request_=reader_.request(analysis_->directory,selected_,cursor_,config_,eventPose_?std::optional<Snapshot>(eventSnapshot({})):std::nullopt);needSeek_=false;}}
    auto version=loaded_?loaded_->version:analysis_->version;if(traceVersion_!=version||changed){renderer_.updateTrajectories(trajectories());traceVersion_=version;output<<"analysis version="<<analysis_->version<<" trajectories="<<renderer_.trajectoryCount()<<" directory="<<analysis_->directory->trials.size()<<" C="<<analysis_->normalTrials<<" B="<<analysis_->contact->hitTrials()<<" M="<<analysis_->contact->missTrials()<<" unknown="<<analysis_->contact->unknown()<<'\n';}
    if(changed||lastTab_!=tab_)rebuildList();if(surfaceVersion_!=analysis_->version||lastTab_!=tab_||lastMetric_!=metric_){auto p=plot();if((tab_==0||tab_==2)&&p.applicable&&p.hits&&!p.hits->empty()&&!analysis_->ioError){double denominator=metric_==0?double(std::max(std::uint64_t(1),*std::max_element(p.hits->begin(),p.hits->end()))):double(p.n);renderer_.updateSurface(*config_,p.grid,*p.hits,denominator,std::to_string(tab_));}surfaceVersion_=analysis_->version;lastTab_=tab_;lastMetric_=metric_;}
}
void AnalysisPanel::beforeInput(int width,int height,bool focused,bool blocked){
    blocked_=blocked;
    if(!focused)editing_=false;Rectangle slider{350,float(height-137),float(std::max(40,width-380)),20};auto t=trial();
    if(updateTimelineCapture(capturing_,focused,!blocked&&t&&t->frames,IsMouseButtonPressed(MOUSE_BUTTON_LEFT),IsMouseButtonDown(MOUSE_BUTTON_LEFT),CheckCollisionPointRec(GetMousePosition(),slider))){
        editing_=false;double fraction=std::clamp(double((GetMousePosition().x-slider.x)/slider.width),0.,1.);seek(t->firstTime+(t->lastTime-t->firstTime)*fraction,"drag");
        if(log_)*log_<<"timeline_pointer x="<<GetMousePosition().x<<" y="<<GetMousePosition().y<<" inside="<<CheckCollisionPointRec(GetMousePosition(),slider)<<" captured="<<capturing_<<'\n';
    }
}
Snapshot AnalysisPanel::eventSnapshot(Snapshot s)const{
    auto e=event();if(!e||e->status!=FirstContactStatus::hit)return s;
    s.time=cursor_;s.center=e->rock.center;s.shapeOrigin=e->rock.shapeOrigin;s.rotation=e->rock.rotation;s.velocity=e->rock.velocity;s.angularVelocity=e->rock.angularVelocity;s.barrier.enabled=config_->barrier.enabled;s.barrier.elastic=config_->barrier.elastic;s.barrier.center=e->barrier.center;s.barrier.rotation=e->barrier.rotation;s.barrier.displacement=dot(e->barrier.center-config_->barrier.center,barrierAxis(config_->barrier));s.barrier.velocity=dot(e->barrier.velocity,barrierAxis(config_->barrier));return s;
}
void AnalysisPanel::jumpEvent(){auto e=event();if(!e||e->status!=FirstContactStatus::hit)return;cursor_=(e->timeLower+e->timeUpper)/2;follow_=playing_=false;eventPose_=needSeek_=true;log("first_contact");if(log_)*log_<<"event_jump trial="<<selected_<<" interval="<<e->timeLower<<','<<e->timeUpper<<" points="<<e->points.size()<<" physics_updates="<<physicsUpdateCount()<<'\n';}
std::optional<std::pair<std::shared_ptr<const PhysicsScene>,Snapshot>>AnalysisPanel::displayPose()const{
    if(follow_||!sample_||!sample_->available||sample_->trialId!=selected_||!sample_->scene)return {};Snapshot s=sample_->snapshot;if(showingEvent())s=eventSnapshot(s);return std::make_pair(sample_->scene,s);
}
void AnalysisPanel::drawWorld(bool showTrails){
    if(!analysis_)return;auto p=plot();if(mode_!=0&&(tab_==0||tab_==2)&&p.applicable&&!analysis_->ioError&&readError_.empty())renderer_.drawSurface();if(showTrails&&mode_!=1){renderer_.drawTrajectories(selected_,alpha_);const auto&all=trajectories();if(!follow_&&selected_<=all.size()&&all[size_t(selected_-1)])renderer_.drawSelectedProgress(*all[size_t(selected_-1)],cursor_);}
    const auto&e=event();if(e&&e->status==FirstContactStatus::hit&&!follow_&&(eventPose_||(cursor_>=e->timeLower&&cursor_<=e->timeUpper)))for(const auto&point:e->points){DrawSphere(vector(point.world),float(std::max(.035,config_->source.geometry.radius*.035)),RED);DrawSphereWires(vector(point.world),float(std::max(.05,config_->source.geometry.radius*.05)),4,8,YELLOW);}
}
void AnalysisPanel::drawEndpoints(Font font,Camera3D camera,int width,int height,float dpi)const{if(showingEvent()){size_t id=0;for(const auto&point:event()->points){auto p=GetWorldToScreenEx(vector(point.world),camera,width,height);if(p.x>=0&&p.x<width&&p.y>=0&&p.y<height){DrawCircleV(p,4*dpi,RED);DrawCircleLines(int(p.x),int(p.y),6*dpi,YELLOW);text(font,"P"+std::to_string(++id),p.x+8*dpi,p.y,int(12*dpi),YELLOW);}}}if(mode_==1)return;for(const auto&t:trajectories()){if(!t||t->points.empty()||t->status==StopReason::running||normalCompletion(t->status))continue;auto p=GetWorldToScreenEx(vector(t->points.back().center),camera,width,height);if(p.x>=0&&p.x<width&&p.y>=0&&p.y<height)text(font,std::to_string(t->trialId)+" "+stopReasonName(t->status),p.x,p.y,int(12*dpi),ORANGE);}}
